/** One-time province/history migration. Inputs are generated by
 * tools/south_america_map.py --index. Review profiles before --apply.
 * The frozen manifest and audit do not require the temporary index files.
 */
const fs = require('node:fs');
const path = require('node:path');
const assert = require('node:assert/strict');
const {parse,children,scalar,words,read,files,root,base,canonical} = require('./audit_map_ownership.cjs');
const manifestPath=path.join(root,'docs/south_america_1444.json');
const profiles=JSON.parse(read(path.join(root,'tools/south_america_1444_profiles.json'))).factions;
const pending=new Map();
const write=(p,t)=>{
 const bom=fs.existsSync(p)&&fs.readFileSync(p).subarray(0,3).equals(Buffer.from([239,187,191]));
 pending.set(p,(bom?'\uFEFF':'')+t);
};
const replace=(t,edits)=>edits.sort((a,b)=>b.start-a.start).reduce((s,e)=>s.slice(0,e.start)+e.text+s.slice(e.end),t);
const add=(map,k,v=1)=>map.set(k,(map.get(k)||0)+v);
function allocate(total,weights){
 const sum=[...weights.values()].reduce((a,b)=>a+b,0);
 const rows=[...weights].map(([k,w])=>({k,n:Math.floor(total*w/sum),r:total*w%sum}));
 let left=total-rows.reduce((n,r)=>n+r.n,0);
 rows.sort((a,b)=>b.r-a.r||a.k.localeCompare(b.k));
 for(let i=0;i<left;i++)rows[i].n++;
 return rows.filter(r=>r.n>0).map(r=>[r.k,r.n]);
}
function main(){
 assert(process.argv.includes('--apply'),'Pass --apply to migrate.');
 assert(!fs.existsSync(manifestPath),'Already migrated; use audit_south_america.cjs.');
 const centres=JSON.parse(read(path.join(root,'tools/south_america_centres.tmp.json')));
 const adjacency=JSON.parse(read(path.join(root,'tools/south_america_adjacency.tmp.json')));
 const regions=JSON.parse(read(path.join(root,'tools/south_america_states.tmp.json')));
 const wanted=new Set(Object.keys(regions));
 const definitions=new Map();
 for(const p of files(path.join(root,'common/country_definitions'))){
  const text=read(p);
  for(const n of parse(text)){
   const tag=n.key.replace('REPLACE:','');
   if(definitions.has(tag)&&/^\w+\s*\?=/.test(text.slice(n.start,n.end)))continue;
   definitions.set(tag,n);
  }
 }
 const oldOwners={},sources=[],provState={},newOwners={},activeBefore=new Set();
 for(const p of files(path.join(root,'common/history/states'))){
  const text=read(p);
  for(const top of parse(text))for(const s of top.value||[]){
   const state=s.key.slice(2);
   if(!wanted.has(state)||!children(s,'create_state').length)continue;
   assert(!oldOwners[state],`Duplicate state ${state}`);
   oldOwners[state]={};newOwners[state]={};sources.push({p,text,s,state});
   for(const c of children(s,'create_state')){
    const tag=scalar(c,'country').slice(2),provs=words(c,'owned_provinces');activeBefore.add(tag);
    oldOwners[state][tag]=provs;
    for(const prov of provs){
     assert(!provState[prov],`Duplicate province ${prov}`);provState[prov]=state;
     newOwners[state][prov]=(scalar(definitions.get(tag),'country_type')==='decentralized'||tag in profiles||tag==='AIMC')?'AMZ':tag;
    }
   }
 }
 }
 assert.equal(Object.keys(oldOwners).length,wanted.size);
 const assigned=new Set();
 // A connected growth frontier avoids isolated province speckles.
 for(const [tag,f]of Object.entries(profiles)){
  const distance=prov=>{const [x,y]=centres[prov];return ((x-f.anchor[0])/f.radius[0])**2+((y-f.anchor[1])/f.radius[1])**2;};
  const eligible=new Set(Object.keys(provState).filter(prov=>centres[prov]&&f.states.includes(provState[prov].replace('STATE_',''))&&newOwners[provState[prov]][prov]==='AMZ'&&!assigned.has(prov)&&distance(prov)<=1));
  const seed=[...eligible].filter(prov=>provState[prov]==='STATE_'+f.capital).sort((a,b)=>distance(a)-distance(b))[0];
  assert(seed,`No seed for ${tag}`);
  const selected=new Set([seed]),frontier=new Set(adjacency[seed].filter(p=>eligible.has(p)));
  while(selected.size<f.provinces&&frontier.size){
   const p=[...frontier].sort((a,b)=>distance(a)-distance(b)||a.localeCompare(b))[0];
   frontier.delete(p);selected.add(p);
   for(const n of adjacency[p]||[])if(eligible.has(n)&&!selected.has(n))frontier.add(n);
  }
  assert(selected.size>=3,`Too small ${tag}: ${selected.size}`);
  for(const p of selected){newOwners[provState[p]][p]=tag;assigned.add(p);}
  console.log(`${tag}: ${selected.size} connected provinces`);
 }
 const mappings={},finalOwners={};
 for(const [state,olds]of Object.entries(oldOwners)){
  finalOwners[state]={};
  for(const [prov,tag]of Object.entries(newOwners[state]))(finalOwners[state][tag]??=[]).push(prov);
  for(const provs of Object.values(finalOwners[state]))provs.sort();
  for(const [old,provs]of Object.entries(olds)){
   const weights=new Map();for(const p of provs)add(weights,newOwners[state][p]);mappings[state+'|'+old]=weights;
  }
 }
 const baseline={population:{},buildings:[],andineOwners:{},orphanScopes:[]};
 for(const [state,olds]of Object.entries(oldOwners))for(const [tag,provs]of Object.entries(olds)){
  if(scalar(definitions.get(tag),'country_type')!=='decentralized'&&!(tag in profiles)&&tag!=='AIMC')baseline.andineOwners[state+'|'+tag]=provs.map(canonical).sort();
 }
 // Ownership declarations, homelands, and claim scopes stay in their original files.
 const stateEdits=new Map();
 for(const {p,text,s,state}of sources){
  const parts=[s.key+' = {'];
  for(const [tag,provs]of Object.entries(finalOwners[state]).sort()){
   parts.push(`\t\tcreate_state = {\n\t\t\tcountry = c:${tag}\n\t\t\towned_provinces = { ${provs.join(' ')} }${tag in profiles?'\n\t\t\tstate_type = incorporated':''}\n\t\t}`);
  }
  for(const n of s.value){
   if(n.key==='create_state')continue;
   if(n.key==='add_claim'&&typeof n.value==='string'){
    const weights=mappings[state+'|'+n.value.slice(2)];
    if(weights){for(const tag of weights.keys())parts.push('\t\tadd_claim = c:'+tag);continue;}
   }
   parts.push('\t\t'+text.slice(n.start,n.end));
  }
  const homelands=new Set(children(s,'add_homeland').map(n=>n.value.slice(3)));
  for(const tag of Object.keys(finalOwners[state]))if(profiles[tag]&&!homelands.has(profiles[tag].culture)){
   parts.push('\t\tadd_homeland = cu:'+profiles[tag].culture);homelands.add(profiles[tag].culture);
  }
  parts.push('\t}');
  if(!stateEdits.has(p))stateEdits.set(p,{text,edits:[]});
  stateEdits.get(p).edits.push({start:s.start,end:s.end,text:parts.join('\n')});
 }
 // Repartition each existing pop by territory overlap. Identity and integer totals are conserved.
 for(const folder of ['pops','buildings'])for(const p of files(path.join(root,'common/history',folder))){
  const text=read(p),edits=[];
  for(const top of parse(text))for(const s of top.value||[]){
   const state=s.key.slice(2);if(!wanted.has(state))continue;
   const groups=new Map();
   for(const region of s.value||[]){
    const old=region.key.replace('region_state:','');
    let weights=mappings[state+'|'+old];
    if(!weights&&region.value?.length){
     // Existing hand-edited history includes stale scopes without territory.
     // Retain their people locally, distributed by the state's current footprint.
     weights=new Map(Object.entries(finalOwners[state]).map(([tag,provs])=>[tag,provs.length]));
     baseline.orphanScopes.push({folder,state,old,method:'current-state province weights'});
    }
    assert(weights||!region.value?.length,`Orphan source ${folder} ${state} ${old}`);
    if(!weights)continue;
    for(const n of region.value||[]){
     if(folder==='pops'&&n.key==='create_pop'){
      const size=Number(scalar(n,'size')),identity=[state,scalar(n,'culture'),scalar(n,'religion'),scalar(n,'pop_type')].join('|');
      baseline.population[identity]=(baseline.population[identity]||0)+size;
      for(const [tag,amount]of allocate(size,weights)){
       const raw=text.slice(n.start,n.end).replace(/\bsize\s*=\s*\d+/,`size = ${amount}`);
       if(!groups.has(tag))groups.set(tag,[]);groups.get(tag).push(raw);
      }
     }else{
      const tag=[...weights].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))[0][0];
      const raw=text.slice(n.start,n.end).replace(new RegExp(`\\bc:${old}\\b`,'g'),'c:'+tag);
      if(!groups.has(tag))groups.set(tag,[]);groups.get(tag).push(raw);
      if(folder==='buildings')baseline.buildings.push({state,raw:raw.replace(/\s+/g,' ')});
     }
    }
   }
   const parts=[s.key+' = {'];
   for(const [tag,items]of [...groups].sort())parts.push(`\t\tregion_state:${tag} = {\n${items.map(n=>'\t\t\t'+n).join('\n')}\n\t\t}`);
   parts.push('\t}');edits.push({start:s.start,end:s.end,text:parts.join('\n')});
  }
  if(edits.length)write(p,replace(text,edits));
 }
 const settlementConcentration=[];
 for(const [tag,f]of Object.entries(profiles)){
  let total=0;const donors=[];
  for(const [p,text]of pending){
   if(!p.includes(path.join('history','pops')))continue;
   for(const top of parse(text))for(const state of top.value||[]){
    if(state.key!=='s:STATE_'+f.capital)continue;
    for(const region of state.value||[])for(const pop of children(region,'create_pop')){
     if(region.key==='region_state:'+tag)total+=Number(scalar(pop,'size'));
     if(region.key==='region_state:AMZ')donors.push({p,text,state,pop,size:Number(scalar(pop,'size'))});
    }
   }
  }
  const needed=Math.max(0,(f.minimumPopulation||12000)-total);
  if(!needed)continue;
  const donor=donors.sort((a,b)=>b.size-a.size)[0];assert(donor&&donor.size>needed,`Insufficient local population: ${tag}`);
  const raw=donor.text.slice(donor.pop.start,donor.pop.end);
  const moved=raw.replace(/\bsize\s*=\s*\d+/,`size = ${needed}`);
  const retained=raw.replace(/\bsize\s*=\s*\d+/,`size = ${donor.size-needed}`);
  const target=children(donor.state,'region_state:'+tag)[0];
  const at=(target||donor.state).end-1;
  const insertion=target?'\n\t\t\t'+moved+'\n\t\t':`\n\t\tregion_state:${tag} = {\n\t\t\t${moved}\n\t\t}\n\t`;
  pending.set(donor.p,replace(donor.text,[{start:donor.pop.start,end:donor.pop.end,text:retained},{start:at,end:at,text:insertion}]));
  settlementConcentration.push({tag,state:'STATE_'+f.capital,transferredFrom:'AMZ',people:needed,minimumPopulation:f.minimumPopulation||12000,reason:'Concentrate existing local settlement population for a viable small-country start; preserve identity and state total.'});
 }
 for(const [p,{text,edits}]of stateEdits)write(p,replace(text,edits));
 // Retain unused old tags for save compatibility, but give every active tag one definition.
 const targetTags=new Set([...Object.keys(profiles),'AMZ']);
 for(const p of files(path.join(root,'common/country_definitions'))){
  const text=read(p),edits=[];
  for(const n of parse(text))if(targetTags.has(n.key.replace('REPLACE:','')))edits.push({start:n.start,end:n.end,text:'# Defined in aoc_south_america_playable.txt'});
  if(edits.length)write(p,replace(text,edits));
 }
 const cultures=new Set();for(const old of activeBefore)for(const culture of words(definitions.get(old),'cultures'))cultures.add(culture);
 cultures.delete('norse');
 const defs=['# Regional playable cores; see docs/south_america_1444.md.'];
 for(const [tag,f]of Object.entries(profiles))defs.push(`${tag} = {\n\tcolor = { ${f.color.join(' ')} }\n\tcountry_type = unrecognized\n\ttier = principality\n\tcultures = { ${[f.culture,...(f.additionalCultures||[])].join(' ')} }\n\tcapital = STATE_${f.capital}\n}`);
 defs.push(`AMZ = {\n\tcolor = { 77 102 78 }\n\tcountry_type = decentralized\n\ttier = principality\n\tcultures = { ${[...cultures].sort().join(' ')} }\n\tcapital = STATE_AMAZONAS\n}`);
 write(path.join(root,'common/country_definitions/aoc_south_america_playable.txt'),defs.join('\n\n')+'\n');
 const laws=['monarchy','autocracy','state_religion','subjecthood','hereditary_bureaucrats','manorial_economy','isolationism'];
 const techs=['agriculture','woodcutting','pottery','legalism','peasant_levy'];
 write(path.join(root,'common/history/countries/aoc_south_america.txt'),'# Shared early government baseline; political tags abstract regional communities.\nCOUNTRIES = {\n'+Object.keys(profiles).map(tag=>`\tc:${tag} = {\n${techs.map(t=>'\t\tadd_technology_researched = '+t).join('\n')}\n${laws.map(l=>'\t\tactivate_law = law_type:law_'+l).join('\n')}\n\t}`).join('\n')+'\n}\n');
 const loc=['\uFEFFl_english:'];
 for(const [tag,f]of Object.entries(profiles))loc.push(` ${tag}: "${f.name}"`,` ${tag}_ADJ: "${f.adjective}"`);
 loc.push(' AMZ: "South American Peoples"',' AMZ_ADJ: "South American"');
 pending.set(path.join(root,'localization/english/replace/zz_aoc_south_america_l_english.yml'),loc.join('\n')+'\n');
 const activeAfter=[...new Set(Object.values(finalOwners).flatMap(Object.keys))].sort();
 const decBefore=[...activeBefore].filter(t=>scalar(definitions.get(t),'country_type')==='decentralized').sort();
 for(const [p,text]of pending)fs.writeFileSync(p,text);
 const coreAdjacency={};
 for(const tag of Object.keys(profiles)){
  const provs=Object.values(finalOwners).flatMap(o=>o[tag]||[]),set=new Set(provs);
  coreAdjacency[tag]=Object.fromEntries(provs.map(p=>[p,(adjacency[p]||[]).filter(n=>set.has(n))]));
 }
 fs.writeFileSync(manifestPath,JSON.stringify({method:'Research profiles + connected locality cores; province-overlap population redistribution.',profiles,oldOwners,finalOwners,baseline,decBefore,activeBefore:[...activeBefore].sort(),activeAfter,settlementConcentration,coreAdjacency},null,2)+'\n');
 console.log(`${decBefore.length} active decentralized tags -> 1; ${Object.keys(profiles).length} playable regional cores; ${activeBefore.size} -> ${activeAfter.length} active South American countries.`);
}
if(require.main===module)main();
module.exports={allocate};
